//! Bounded genuine DOM traversal in a dedicated isolated world. No framework internals.
pub(super) const WALK: &str = r#"(()=>{const refs=[],nodes=[];let budget=131072,truncated=false;const cut=(v,n)=>{let s=String(v??'').slice(0,n);const last=s.charCodeAt(s.length-1);if(last>=0xD800&&last<=0xDBFF)s=s.slice(0,-1);return s.toWellFormed()};function visit(node,parent,depth,shadow){if(refs.length>=500||depth>8||budget<=0){truncated=true;return}const index=refs.length;const attributes=[];if(node.nodeType===1){for(let i=0;i<Math.min(node.attributes.length,16);i++){const a=node.attributes[i];const name=cut(a.name,64),value=cut(a.value,256);if(name.length+value.length>budget){truncated=true;break}budget-=name.length+value.length;attributes.push([name,value])}}const name=cut(node.nodeName,128),localName=cut(node.localName,128),value=cut(node.nodeValue,256);budget-=name.length+localName.length+value.length;if(budget<0){truncated=true;return}refs.push(node);nodes.push({parent,depth,name,localName,value,attributes,nodeType:node.nodeType,childCount:node.childNodes.length,shadow});if(depth>=8){if(node.firstChild||(node.nodeType===1&&node.shadowRoot))truncated=true;return}if(node.nodeType===1&&node.shadowRoot)visit(node.shadowRoot,index,depth+1,true);let child=node.firstChild;while(child){if(refs.length>=500||budget<=0){truncated=true;break}visit(child,index,depth+1,false);child=child.nextSibling}}visit(document,null,0,false);return{refs,nodes,truncated}})()"#;
pub(super) const NODES: &str = "function(){return {nodes:this.nodes,truncated:this.truncated}}";
pub(super) const NODE: &str = "function(index){return this.refs[index]}";
pub(super) const DETAILS: &str = "function(){if(this.nodeType!==1)return{attributes:[],styles:[]};const attributes=[];for(let i=0;i<Math.min(this.attributes.length,32);i++){const a=this.attributes[i];attributes.push([a.name.slice(0,256).toWellFormed(),a.value.slice(0,1024).toWellFormed()])}const computed=getComputedStyle(this),styles=[];for(let i=0;i<Math.min(computed.length,512);i++){const name=computed[i];styles.push([name.slice(0,256).toWellFormed(),computed.getPropertyValue(name).slice(0,1024).toWellFormed()])}return{attributes,styles}}";
